output_text:
[
  {
    "id": "no_carts_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file side aisles flanked by shelves.",
    "abstraction": {
      "state_properties": {
        "single_file": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "opposing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "single_file",
            "opposing_shelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_side_aisle",
    "text": "An agent must not enter a single-file shelf aisle while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "move_action": {
          "or": [
            "N",
            "S",
            "E",
            "W"
          ]
        },
        "single_file": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "opposing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "single_file",
            "opposing_shelves"
          ]
        }
      },
      "events": {
        "enter_single_file_shelf_aisle_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "move_action"
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_shelf_aisle_with_cart"
    }
  },
  {
    "id": "park_only_at_side_aisle_mouths",
    "text": "Carts may be parked only at designated wide bays at the mouths of the single-file side aisles.",
    "abstraction": {
      "state_properties": {
        "side_aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wide_bay": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "approved_cart_parking_bay": {
          "and": [
            "side_aisle_mouth",
            "wide_bay"
          ]
        }
      },
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "park_cart",
          {
            "not": "approved_cart_parking_bay"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever an agent parks a cart at a side-aisle bay, they are obliged to retrieve it before finishing.",
    "abstraction": {
      "state_properties": {
        "cart_parking_bay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "park_cart_at_bay": {
          "pre": {
            "and": [
              "cart_parking_bay",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieve_cart_at_bay": {
          "pre": {
            "and": [
              "cart_parking_bay",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart_at_bay",
      "discharge": "retrieve_cart_at_bay"
    }
  },
  {
    "id": "cart_required_for_standard_shelves",
    "text": "Interactions with ordinary shelf faces in the wider shopping aisles must be performed with a cart.",
    "abstraction": {
      "state_properties": {
        "single_file": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "opposing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "single_file",
            "opposing_shelves"
          ]
        },
        "standard_shelf_face": {
          "and": [
            "adjShelf",
            {
              "not": "single_file_shelf_aisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "standard_shelf_face",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_on_open_sales_floor",
    "text": "Away from the entrance, parking bays, and single-file side aisles, shoppers on the open sales floor must have their cart.",
    "abstraction": {
      "state_properties": {
        "entrance_zone": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cart_parking_bay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "single_file": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "open_sales_floor": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                2
              ]
            },
            {
              "not": "entrance_zone"
            },
            {
              "not": "cart_parking_bay"
            },
            {
              "not": "single_file"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "open_sales_floor",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_no_west_in_aisles",
    "text": "Customer aisles are one-way, so westward travel in a traversable aisle is prohibited.",
    "abstraction": {
      "state_properties": {
        "customer_aisle": {
          "ge": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "customer_aisle",
          "W"
        ]
      }
    }
  },
  {
    "id": "take_cart_before_leaving_entrance",
    "text": "After reaching the entrance cart bay, an agent must not leave the entrance area without taking a cart.",
    "abstraction": {
      "state_properties": {
        "move_action": {
          "or": [
            "N",
            "S",
            "E",
            "W"
          ]
        },
        "entrance_cart_bay": "at(1,7)",
        "entrance_area": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "outside_entrance_area": {
          "not": "entrance_area"
        }
      },
      "events": {
        "leave_entrance_without_cart": {
          "pre": {
            "and": [
              "entrance_cart_bay",
              {
                "not": "hasCart"
              },
              "move_action"
            ]
          },
          "post": "outside_entrance_area"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_entrance_without_cart"
    }
  }
]
